-- scripts/ui/screens/farm.lua
local UI = require("urhox-libs/UI")

local function buildFarmScreen(onAction)
  return UI.SafeAreaView {
    width = "100%",
    height = "100%",
    backgroundColor = UI.Theme.Color("background"),
    children = {
      UI.Panel {
        width = "100%",
        height = "100%",
        flexDirection = "column",
        padding = { 16, 24, 16, 24 },
        gap = 16,
        children = {
          UI.Label { text = "农田主页", fontSize = 22, fontWeight = "bold" },
          -- map components via exports/taptap-maker/component-map.json
          UI.Button {
            text = "开始",
            variant = "primary",
            onClick = function() if onAction then onAction("primary") end end,
          },
        },
      },
    },
  }
end

return { id = "farm", build = buildFarmScreen }
